DO $$BEGIN
 PERFORM public.qa_run_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000007');
 PERFORM public.qa_batch_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000007',jsonb_build_array(public.qa_record_v403('transaction','t1',11)));
 BEGIN PERFORM public.qa_finish_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000007',2);RAISE EXCEPTION 'incomplete success accepted';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE '%INCOMPLETE_SUCCESS_NOT_ALLOWED%'THEN RAISE;END IF;END;
